-- Healthcare Claims & Revenue Cycle Analytics
-- PostgreSQL data loader generated from the project's synthetic CSV files.
-- Run this AFTER 01_create_schema_postgresql.sql while connected to healthcare_rcm.

BEGIN;

-- Makes the script safe to rerun during portfolio development.
TRUNCATE TABLE claims, patients, diagnoses, procedures, providers, payers CASCADE;

-- Load payers: 8 rows

-- Load providers: 30 rows

-- Load procedures: 16 rows

-- Load diagnoses: 12 rows

-- Load patients: 900 rows




-- Load claims: 6,000 rows












COMMIT;

-- Verification
SELECT 'payers' AS table_name, COUNT(*) AS row_count FROM payers
UNION ALL
SELECT 'providers', COUNT(*) FROM providers
UNION ALL
SELECT 'procedures', COUNT(*) FROM procedures
UNION ALL
SELECT 'diagnoses', COUNT(*) FROM diagnoses
UNION ALL
SELECT 'patients', COUNT(*) FROM patients
UNION ALL
SELECT 'claims', COUNT(*) FROM claims
ORDER BY table_name;
